    /// Hilfe: (Überschrift, Text) je Abschnitt.
    public static (string head, string body)[] HelpSections => En ? HelpEn : HelpDe;

    private static readonly (string, string)[] HelpDe =
    {
        ("Überblick", "Das Programm ersetzt NZXT CAM für die drei Lüfter am NZXT-Controller. Es liest jede Sekunde CPU- und GPU-Temperatur und stellt die Lüfter nach ihrer Kurve ein. NZXT CAM darf nicht gleichzeitig laufen."),
        ("Kacheln", "Jede Kachel zeigt einen Lüfter: Drehzahl, Leistung in Prozent, Temperatur und Kurve. Klicken wählt den Lüfter für die Kurve aus. Mit gedrückter Maustaste lässt sich eine Kachel auf eine andere ziehen, um die Reihenfolge zu ändern. Der Stift ✎ öffnet „Lüfter bearbeiten“: Name, an welcher LED-Zone der Lüfter hängt und die Farbe seines Lüfterrads."),
        ("Speichern und Rückgängig", "Änderungen an Kurve, Zuordnung und Beleuchtung werden erst wirksam, wenn du in der Leiste unten auf „Speichern“ klickst. Die Leiste erscheint nur, wenn etwas ungespeichert ist, und sagt, was. „Verwerfen“ stellt den gespeicherten Stand wieder her. Der Knopf ↶ oben (oder Strg+Z) macht die letzten Schritte einzeln rückgängig, auch Farben und Namen."),
        ("Kurven", "Eine Kurve legt fest, wie schnell ein Lüfter bei welcher Temperatur läuft (20–100 °C). Kurven sind eigenständig und können von mehreren Lüftern und Profilen genutzt werden. Punkte mit der Maus ziehen, dann „Kurve speichern“. Die Änderung wirkt auf alle Lüfter mit dieser Kurve. „Als neue Kurve“ legt eine Kopie unter neuem Namen an."),
        ("Profile", "Ein Profil speichert die gesamte Abstimmung: welche Kurve jeder Lüfter nutzt, ob er sich nach CPU oder GPU richtet, und die Beleuchtung. Änderungen an der Abstimmung werden erst mit „Profil speichern“ wirksam. Über das Auswahlfeld wechselst du zwischen Profilen."),
        ("Sicherheit", "Ab 80 °C gilt immer eine Mindestdrehzahl, egal wie die Kurve aussieht: 30 % bei 80 °C bis 100 % bei 95 °C. Fällt ein Temperaturfühler aus, laufen die Lüfter mit 60 %. Beim Beenden setzt das Programm alle Lüfter auf 50 %, damit sie nie stehen bleiben. Die Drehzahl steigt schnell (bis 10 % pro Sekunde) und fällt langsam (3 % pro Sekunde). Nach einem Standby verbindet sich das Programm selbst neu."),
        ("Beleuchtung", "Unter „Beleuchtung“ wird jedes eingeschaltete Gerät angezeigt. Pro Zone: Aus, feste Farbe oder Farbe nach CPU- bzw. GPU-Temperatur (Farbverlauf mit frei wählbaren Punkten). Alternativ ein Effekt des Geräts für das ganze Gerät. Änderungen sieht man sofort am PC, gespeichert werden sie mit „Profil speichern“. Die Beleuchtung läuft über OpenRGB, das unsichtbar im Hintergrund gestartet wird. Welche Geräte gesteuert werden, legst du in den Einstellungen unter „Geräte“ fest."),
        ("Lüfter und Lichtkanäle zuordnen", "Das Programm kann nicht erkennen, welcher Lüfter an welchem Lichtkanal des Controllers steckt. Anfangs sind alle Lüfter dem ersten Kanal zugeordnet. Stelle es einmal richtig ein: Stift ✎ in der Lüfterkachel, bei „Hängt an LED-Zone“ den Kanal wählen, an dem die LEDs dieses Lüfters hängen, dann speichern. Welcher Kanal welcher ist, siehst du am schnellsten, wenn du unter „Beleuchtung“ einer Zone kurz eine auffällige feste Farbe gibst. Die Zuordnung bestimmt, welche Lüfter bei einer Zone genannt werden und welche Farbe ein Lüfterrad mit „Wie seine Beleuchtung“ zeigt."),
        ("Start der Beleuchtung", "Nach dem Programmstart dauert es etwa 15 bis 20 Sekunden, bis die Beleuchtung reagiert. In dieser Zeit erkennt OpenRGB die LEDs am Controller, und die Lüfter behalten ihren letzten Wert. Leuchtet danach nur ein Teil der LEDs, beende das Programm ganz, schließe ein eventuell noch laufendes OpenRGB und starte neu."),
        ("Andere PCs", "Unterstützt wird ein NZXT Smart Device V2 oder RGB & Fan Controller mit drei Lüfterkanälen. Es werden immer drei Kacheln gezeigt; ein freier Kanal ist abgeblendet und als „nicht angeschlossen“ beschriftet. Mehrere Lüfter an einem Kanal (Verteiler) zählen als einer. Lüfter am Mainboard und andere Lüftersteuerungen werden nicht gesteuert. Beleuchtung: alle Geräte, die OpenRGB erkennt, erscheinen in den Einstellungen unter „Geräte“."),
        ("Farbe der Oberfläche", "In den Einstellungen wählst du eine feste Farbe für die Knöpfe oder lässt sie der Gehäusebeleuchtung folgen. Lüfterräder und Kurve lassen sich getrennt davon färben: wie die Oberfläche, mit fester Farbe (je Lüfter), wie eine Beleuchtungszone (die Räder leuchten dann wie die echten Lüfter) oder als animierter RGB-Regenbogen."),
        ("Infobereich und Autostart", "Das Programm läuft im Infobereich unten rechts. Das X schließt nur das Fenster. Ganz beenden über Rechtsklick auf das Symbol. In den Einstellungen lässt sich festlegen, ob Minimieren in die Taskleiste oder nur in den Infobereich geht, und ob das Programm mit Windows startet."),
        ("PawnIO", "Für die CPU-Temperatur braucht das Programm den Treiber PawnIO (pawnio.eu). Er wird beim Start geprüft. Fehlt er, erscheint ein Hinweis, und Lüfter nach CPU laufen mit 60 %."),
        ("Dateien", "Einstellungen und Protokoll liegen in %APPDATA%\\NzxtFan (config.json, log.txt). Der Ordner lässt sich in den Einstellungen öffnen."),
    };

    private static readonly (string, string)[] HelpEn =
    {
        ("Overview", "This program replaces NZXT CAM for the three fans on the NZXT controller. Every second it reads CPU and GPU temperature and sets the fans according to their curve. NZXT CAM must not run at the same time."),
        ("Tiles", "Each tile shows one fan: speed, duty in percent, temperature and curve. Click to select the fan for the curve editor. Drag a tile onto another to change the order. The pencil ✎ opens “Edit fan”: name, which LED zone the fan is connected to and the color of its wheel."),
        ("Save and undo", "Changes to curve, assignment and lighting take effect when you click “Save” in the bar at the bottom. The bar only appears when something is unsaved and tells you what. “Discard” restores the saved state. The ↶ button at the top (or Ctrl+Z) undoes the last steps one by one, including colors and names."),
        ("Curves", "A curve defines how fast a fan runs at which temperature (20–100 °C). Curves are independent and can be used by several fans and profiles. Drag the points, then “Save curve”. The change applies to every fan using that curve. “Save as new” stores a copy under a new name."),
        ("Profiles", "A profile stores the whole tuning: which curve each fan uses, whether it follows CPU or GPU, and the lighting. Tuning changes take effect after “Save profile”. Use the drop-down to switch profiles."),
        ("Safety", "From 80 °C a minimum speed always applies, whatever the curve looks like: 30 % at 80 °C up to 100 % at 95 °C. If a temperature sensor fails, fans run at 60 %. On exit all fans are set to 50 % so they never stop. Speed rises fast (up to 10 % per second) and falls slowly (3 % per second). After standby the program reconnects by itself."),
        ("Lighting", "The “Lighting” tab shows every enabled device. Per zone: off, a fixed color or a color by CPU or GPU temperature (gradient with free points). Alternatively a device effect for the whole device. Changes are visible on the PC at once and are stored with “Save profile”. Lighting runs through OpenRGB, which is started invisibly in the background. Choose the controlled devices in the settings under “Devices”."),
        ("Assigning fans to light channels", "The program cannot detect which fan is plugged into which light channel of the controller. Initially all fans are assigned to the first channel. Set it once: pencil ✎ in the fan tile, under “Connected to LED zone” pick the channel this fan's LEDs are connected to, then save. The quickest way to tell the channels apart is to give one zone a striking fixed color in the “Lighting” tab for a moment. The assignment decides which fans are listed for a zone and which color a fan wheel shows with “Like its lighting”."),
        ("Lighting startup", "After the program starts it takes about 15 to 20 seconds until the lighting responds. During that time OpenRGB detects the LEDs on the controller and the fans keep their last value. If only part of the LEDs light up afterwards, quit the program completely, close any OpenRGB that is still running and start again."),
        ("Other PCs", "Supported is one NZXT Smart Device V2 or RGB & Fan Controller with three fan channels. Three tiles are always shown; an unused channel is dimmed and labelled “not connected”. Several fans on one channel (splitter) count as one. Fans on the mainboard and other fan controllers are not controlled. Lighting: every device OpenRGB detects appears in the settings under “Devices”."),
        ("Interface color", "In the settings you pick a fixed color for the buttons or let it follow the case lighting. Fan wheels and curve can be colored separately: like the interface, a fixed color (per fan), like a lighting zone (the wheels then glow like the real fans) or as an animated RGB rainbow."),
        ("Tray and autostart", "The program lives in the notification area. The X only closes the window. Quit via right-click on the icon. In the settings you choose whether minimizing goes to the taskbar or only to the tray, and whether the program starts with Windows."),
        ("PawnIO", "For the CPU temperature the program needs the PawnIO driver (pawnio.eu). It is checked on startup. If it is missing a notice appears and CPU-based fans run at 60 %."),
        ("Files", "Settings and log are stored in %APPDATA%\\NzxtFan (config.json, log.txt). The folder can be opened from the settings."),
    };

    public static string T(string key, params object[] args)
    {
        if (!S.TryGetValue(key, out var v)) return key;
        var s = En ? v.en : v.de;
        return args.Length == 0 ? s : string.Format(s, args);
    }
}
